def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 5 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    p = (y+dy, x+dx)
                    if 0 <= p[0] < h and 0 <= p[1] < w and grid[p[0]][p[1]] == 5 and p not in seen:
                        seen.add(p)
                        stack.append(p)
            r0 = min(y for y,x in comp); r1 = max(y for y,x in comp)
            c0 = min(x for y,x in comp); c1 = max(x for y,x in comp)
            # The 5 outline is a box with a single missing cell in its top edge.
            top = [x for x in range(c0, c1+1) if grid[r0][x] != 5]
            if len(top) != 1:
                continue
            gap = top[0]
            for y in range(r0+1, r1):
                for x in range(c0+1, c1):
                    if grid[y][x] == 0:
                        out[y][x] = 2
            if r0 > 0:
                for x in range(gap+1):
                    out[r0-1][x] = 2
    return out
